package com.sami.app.uom.dto;
import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.Instant;
public final class UomDtos { private UomDtos(){} public record UomRequest(@NotBlank @Size(max=32) String code,@NotBlank @Size(max=120) String name,@NotBlank String status){} public record UomResponse(Long id,String code,String name,String status,Instant createdAt,Instant updatedAt,Long version){} public record ConversionRequest(@NotNull Long fromUomId,@NotNull Long toUomId,@NotNull @DecimalMin("0.000000000001") BigDecimal factor,@NotBlank String status){} public record ConversionResponse(Long id,Long fromUomId,Long toUomId,BigDecimal factor,String status,Instant createdAt,Instant updatedAt,Long version){} public record QuantityConversion(BigDecimal quantity,Long fromUomId,Long toUomId,BigDecimal factor,BigDecimal convertedQuantity){} }
